INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z20-q40','nism-5b-z20','An investment of ₹54,000 grows to ₹1,08,613 in 5 years. The compounded annual growth rate (CAGR) is closest to:','["17.0%","20.2%","15.0%","13.0%"]',2,'CAGR = (end/start)^(1/5) − 1 ≈ 15%.',40) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z20-q41','nism-5b-z20','The Statement of Additional Information (SAI) is:','["Prepared by AMFI","One document covering all schemes of a mutual fund","Prepared by the distributor","Scheme-specific"]',1,'The SAI is legally part of the SID.',41) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z20-q42','nism-5b-z20','After the launch of an open-ended scheme, the SID must first be updated within ___ of the half-year end.','["6 months","1 month","1 year","3 months"]',0,'Then within 1 month of each half-year (Sept/Mar).',42) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z20-q43','nism-5b-z20','The Sharpe ratio is:','["(Scheme return − risk-free return) ÷ standard deviation","Return ÷ expenses","(Scheme return − risk-free return) ÷ beta","Alpha ÷ beta"]',0,'A higher ratio is better.',43) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z20-q44','nism-5b-z20','Pledged units cannot be sold or switched until:','["The pledgee gives a written NOC","The unitholder dies","SEBI approves","The AMC approves"]',0,'Units must be out of lock-in to be pledged.',44) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z20-q45','nism-5b-z20','An investor invests ₹1,47,000 in an open-ended scheme at an NAV of ₹90.10. With no entry load, the number of units allotted is:','["1595.619","1631.521","14700.000","13244700.000"]',1,'Units = 147000 ÷ 90.10 = 1631.521.',45) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z20-q46','nism-5b-z20','The three mandatory scheme-related documents are:','["KYC, KIM and CAS","SID, TER and CAS","SAI, SEBI circular and factsheet","SID, SAI and KIM"]',3,'The fund factsheet is non-mandatory.',46) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z20-q47','nism-5b-z20','EIC framework stands for:','["Economy, Industry, Company","Equity, Income, Credit","Earnings, Interest, Cash","Exposure, Index, Cap"]',0,'It is used in fundamental analysis.',47) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z20-q48','nism-5b-z20','Mutual fund portfolios must be disclosed on websites within:','["10 days of month-end/half-year","1 year","30 days","3 months"]',0,'Debt schemes also disclose a fortnightly portfolio within 5 days.',48) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z20-q49','nism-5b-z20','Compounded return is valid using NAV only if:','["The scheme is debt","The scheme is close-ended","There is an exit load","No IDCW was paid in the period"]',3,'Otherwise the SEBI reinvestment method is used.',49) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z20-q50','nism-5b-z20','ELSS investors can claim deduction under Section 80C up to:','["₹5,00,000 under the Old Tax Regime","₹1,50,000 under the Old Tax Regime","₹50,000 under any regime","₹2,50,000 under the New Tax Regime"]',1,'Deduction up to ₹1.5 lakh, Old Tax Regime only.',50) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z20-q51','nism-5b-z20','Under two-tier benchmarking, Tier 1 is:','["The risk-free rate","A broad market index per category","The additional benchmark","A bespoke index"]',1,'Tier 2 is more specific to the style.',51) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z20-q52','nism-5b-z20','Rating migration risk means:','["Moving from debt to equity","A downgrade (for example AAA to AA+) lowers the price of the paper","Moving to another rating agency","A rating upgrade lowers price"]',1,'It is a risk in debt funds.',52) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z20-q53','nism-5b-z20','A Fixed Maturity Plan is:','["An ETF on gold","A hybrid scheme with a glide path","A close-ended debt scheme with a portfolio matched to maturity","An open-ended equity scheme"]',2,'FMP returns are not guaranteed, only clearer.',53) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z20-q54','nism-5b-z20','Gating in a mutual fund can be applied for a maximum of:','["30 days in a year","10 working days in any 90-day period","5 days in a month","90 days in a year"]',1,'Only for systemic crises with AMC Board and Trustee approval.',54) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z20-q55','nism-5b-z20','A Transfer of IDCW Plan (DTP) invests the IDCW of one scheme into:','["A scheme of any AMC","Another scheme of the same MF","A bank deposit","The same scheme at face value"]',1,'It overrides payout or reinvestment.',55) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z20-q56','nism-5b-z20','With a scheme return of 7%, risk-free 5% and standard deviation 0.5%, the Sharpe ratio is:','["2","14","0.25","4"]',3,'(7 − 5) ÷ 0.5 = 4.',56) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z20-q57','nism-5b-z20','A fund returned 11% with a standard deviation of 17%. The risk-free rate is 6%. The Sharpe ratio is:','["1.00","0.26","0.65","0.29"]',3,'Sharpe = (11 − 6) ÷ 17.',57) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z20-q58','nism-5b-z20','An investor sells equity-oriented fund units after 18 months with a long-term capital gain of ₹6,75,000 (no other LTCG in the year). As per the rates in the current workbook, the LTCG tax (ignoring cess) is:','["₹1,10,000","₹84,375","₹68,750","₹1,35,000"]',2,'Taxable = 675000 − 1,25,000; tax at 12.5% = ₹68,750.',58) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z20-q59','nism-5b-z20','A scheme with average net assets of ₹4700 crore incurs total recurring expenses of ₹1.00 crore in a year. Its expense ratio is:','["0.011%","0.032%","0.043%","0.021%"]',3,'TER = 1.00 ÷ 4700 × 100 = 0.021%.',59) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z20-q60','nism-5b-z20','Daily trail commission is calculated as:','["AUM × trail rate p.a. ÷ 365","NAV × units","Units × face value","AUM × trail rate ÷ 12 ÷ 100"]',0,'Paid monthly or quarterly.',60) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z20-q61','nism-5b-z20','GST on distributor commission is payable when annual turnover exceeds:','["₹40 lakh","₹10 lakh","₹1 crore","₹20 lakh"]',3,'Reverse charge applies to unregistered suppliers.',61) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z20-q62','nism-5b-z20','Weekly standard deviation is annualised by multiplying by:','["√252","√52","√12","52"]',1,'Monthly × √12; daily × √252.',62) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z20-q63','nism-5b-z20','With a scheme return of 8%, risk-free 5% and beta 1.2, the Treynor ratio is:','["1.5","2.5","3.0","0.6"]',1,'(8 − 5) ÷ 1.2 = 2.5.',63) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z20-q64','nism-5b-z20','Information Ratio equals:','["Alpha ÷ beta","(Portfolio return − benchmark return) ÷ standard deviation of excess return","Return ÷ expenses","Return ÷ beta"]',1,'The denominator is the tracking error.',64) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
