INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z20-q83','nism-5b-z20','An investment of ₹56,000 grows to ₹1,48,961 in 7 years. The compounded annual growth rate (CAGR) is closest to:','["23.7%","15.0%","17.0%","13.0%"]',1,'CAGR = (end/start)^(1/7) − 1 ≈ 15%.',83) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z20-q84','nism-5b-z20','The time used to decide the applicable NAV for a physical application is the time at:','["Cheque clearing","The Official Point of Acceptance","The fund manager''s desk","Handing the form to the distributor"]',1,'Time-stamping machines are tamper-proof.',84) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z20-q85','nism-5b-z20','An investor redeems equity-oriented fund units after 8 months with a short-term capital gain of ₹22,000. The STCG tax (ignoring cess) is:','["₹2,200","₹3,300","₹2,750","₹4,400"]',3,'STCG on equity-oriented funds is 20%: ₹4,400.',85) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z20-q86','nism-5b-z20','A scheme has total assets of ₹492.00 crore, liabilities (other than to unitholders) of ₹7.90 crore and 4.00 crore units outstanding. Its NAV per unit is:','["₹123.00","₹124.98","₹96.82","₹121.03"]',3,'NAV = (492.00 − 7.90) ÷ 4.00 = ₹121.03.',86) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z20-q87','nism-5b-z20','In a joint folio, all benefits (IDCW, redemption proceeds, tax) go to the:','["Second holder","First holder","All holders equally","Youngest holder"]',1,'The folio is in the first holder''s name.',87) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
