INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-7-z0-q0','nism-7-z0','Securities Transaction Tax on equity delivery sale is applied at 0.1% on a sale of ₹22,00,000. The STT is:','["₹550","₹2,200","₹220","₹22,000"]',1,'STT = 0.1% of the sale value (delivery).',0) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-7-z0-q1','nism-7-z0','On a day, a member buys shares worth ₹2,50,000 and sells shares worth ₹1,50,000 (same client, same settlement). The net obligation is:','["₹1,00,000","₹4,00,000","₹1,50,000","₹2,50,000"]',0,'Net obligation = |buys − sells|.',1) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-7-z0-q2','nism-7-z0','A client trades ₹55,00,000 of a stock with a VaR margin of 10%. The VaR margin is:','["₹8,25,000","₹5,50,000","₹2,75,000","₹55,00,000"]',1,'VaR margin = turnover × VaR %.',2) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-7-z0-q3','nism-7-z0','The Settlement Guarantee Fund (SGF) is maintained to:','["Guarantee settlement if a member defaults","Fund IPOs","Pay brokerage","Pay dividends"]',0,'It is maintained by the clearing corporation.',3) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-7-z0-q4','nism-7-z0','A client buys 250 shares at ₹125 with brokerage of 0.3% of the trade value. The brokerage is:','["₹93.75","₹1,04,166.67","₹937.50","₹75.00"]',0,'Brokerage = value × rate.',4) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
